import {Item, ItemStatus, List, Product, UpdateItemData} from "../../models/data.model";
import {ItemDB as ItemDB, ItemDBUpdateType, ListDB as ListDB, ProductDB as ProductDB} from "./data.model";
import { Injectable } from "@angular/core";

@Injectable({ providedIn: 'root' })
export class DataMapperService {

  mapProductFromDB(product: ProductDB): Product {
    return {
      id: product.id!,
      name: product.name,
      comment: product.comment || null,
      imageId: product.imageId || null
    };
  }

  mapItemFromDB(item: ItemDB, product: ProductDB): Item {
    return {
      id: item.id!,
      status: this.toItemStatus(item.status),
      groupColor: item.groupColor || null,
      count: item.count,
      product: this.mapProductFromDB(product),
    };
  }

  mapListFromDB(list: ListDB, items: Item[]): List {
    return {
      id: list.id!,
      name: list.name,
      comment: list.comment || null,
      imageId: list.imageId || null,
      items: items
    };
  }

  private toItemStatus(value: string): ItemStatus {
    return Object.values(ItemStatus).includes(value as ItemStatus)
      ? (value as ItemStatus)
      : ItemStatus.ToBuy;
  }

  mapItemToDBUpdate(item: UpdateItemData): ItemDBUpdateType {
    return {
      count: item.count || undefined,
      status: item.status || undefined,
      groupColor: item.groupColor || undefined
    };
  }
}
