import {inject, Injectable} from "@angular/core";
import Dexie, {liveQuery, Table} from "dexie";
import {
  CreateItemData,
  CreateListData,
  Item,
  List,
  UpdateItemData,
  UpdateListData
} from "../../models/data.model";
import {
  ImageDB,
  ImageDBInsertType,
  ItemDB,
  ItemDBInsertType, ItemDBUpdateType,
  ListDB,
  ListDBInsertType, ListDBUpdateType,
  ProductDB,
  ProductDBInsertType
} from "./data.model";
import {from, Observable} from "rxjs";
import {DataRepositoryState, ImageRepository, ItemRepository, ListRepository} from "../repository";
import {DataMapperService} from "./data-mapper.service";
import dexieCloud from 'dexie-cloud-addon'
import {environment as env} from "../../../environments/environment";

@Injectable({providedIn: 'root'})
export class DexieDataBase extends Dexie implements ImageRepository, ItemRepository, ListRepository {

  private readonly dataMapper = inject(DataMapperService);

  private readonly products!: Table<ProductDB, string, ProductDBInsertType>;
  private readonly items!: Table<ItemDB, string, ItemDBInsertType>;
  private readonly lists!: Table<ListDB, string, ListDBInsertType>;
  private readonly images!: Table<ImageDB, string, ImageDBInsertType>;
  private readonly imageUploadQueue!: Table<string, string>;

  private isDbOpen = false;
  private error: string | null = null;

  constructor() {
    super('AppDatabase', {
      addons: [dexieCloud],
    })
    this.version(1).stores({
      products: '@id, &name',
      items: '@id, productId, listId, groupColor, status',
      lists: '@id, &name',
      images: '@id, &name, updatedAt',
      imageUploadQueue: 'imageId'
    });

    this.products = this.table('products');
    this.items = this.table('items');
    this.lists = this.table('lists');
    this.images = this.table('images');
    this.imageUploadQueue = this.table('imageUploadQueue');

    this.cloud.configure({
      databaseUrl: env.publicDexieCloudDbUrl,
      requireAuth: false,
      customLoginGui: false,
      unsyncedTables: ['images'],
    });

    this.open()
      .then(() => this.isDbOpen = true)
      .catch((e) => this.error = e.message);
  }

  getState(): DataRepositoryState {
    return {
      isDbOpen: this.isDbOpen,
      error: this.error
    };
  }

  createItemInList(listId: string, item: CreateItemData): Observable<string> {
    return from(this.transaction('rw', this.lists, this.items, this.products, async () => {
      const list = await this.lists.get(listId);
      if (!list || !list.id) {
        throw new Error(`Could not find list with id ${listId}`);
      }

      const {product, ..._item} = item;
      const productDB = await this.products.where('name').equalsIgnoreCase(product.name).first();
      let productId: string;
      if (productDB && productDB.id) {
        productId = productDB.id;
      } else {
        const newProductDB: ProductDBInsertType = {
          name: product.name,
          imageId: product.imageId || undefined,
          comment: product.comment || undefined
        };

        productId = await this.products.add(newProductDB);
      }

      const itemDB = ({
        ..._item,
        productId: productId,
        listId: list.id,
        groupColor: _item.groupColor || undefined
      });
      return this.items.add(itemDB);
    }));
  }

  updateItem(id: string, item: UpdateItemData): Observable<number> {
    const _item: ItemDBUpdateType = this.dataMapper.mapItemToDBUpdate(item);
    return from(this.items.update(id, _item));
  }

  deleteItem(id: string): Observable<void> {
    return from(this.items.delete(id));
  }

  createList(listData: CreateListData): Observable<string> {
    return from(this.transaction('rw', this.lists, async () => {
      const list: ListDBInsertType = {
        name: listData.name,
        comment: listData.comment || undefined,
        imageId: listData.imageId || undefined
      }

      return this.lists.add(list);
    }));
  }

  //TODO: replace this eager loading with simple queries and lazy loading
  getAllLists(): Observable<List[]> {
    return from(liveQuery(() => this.transaction('r', this.lists, this.items, this.products, async () => {
      const [lists, itemDBs, products] = await Promise.all([
        this.lists.toArray(),
        this.items.toArray(),
        this.products.toArray(),
      ]);

      const productMap = new Map(products.map(p => [p.id!, p]));

      const itemsByList = new Map<string, Item[]>();
      for (const itemDB of itemDBs) {
        const productDB = productMap.get(itemDB.productId);
        if (!productDB) {
          throw new Error(`Product ${itemDB.productId} not found`);
        }
        const item = this.dataMapper.mapItemFromDB(itemDB, productDB);
        if (!itemsByList.has(itemDB.listId)) {
          itemsByList.set(itemDB.listId, []);
        }
        itemsByList.get(itemDB.listId)!.push(item);
      }

      return lists.map(listDB => {
        const items = itemsByList.get(listDB.id!) ?? [];
        return this.dataMapper.mapListFromDB(listDB, items);
      });
    })));
  }

  getListById(id: string): Observable<List> {
    return from(liveQuery(() => this.transaction('r', this.lists, this.items, this.products, async () => {
      const listDB = await this.lists.get(id);
      if (!listDB) {
        throw new Error(`List ${id} not found`);
      }

      const itemsDB = await this.items.where('listId').equals(id).toArray();
      const productIds = [...new Set(itemsDB.map(i => i.productId))];
      const products = await this.products.bulkGet(productIds);
      console.log(`Loaded list ${id} from DB:`, products);

      const itemsWithProduct = itemsDB.map(itemDB => {
        const productDB = products.find(p => p?.id === itemDB.productId)!;
        return this.dataMapper.mapItemFromDB(itemDB, productDB);
      });

      const list = this.dataMapper.mapListFromDB(listDB, itemsWithProduct);
      console.log('Loaded list from DB:', list);
      return list;
    })));
  }

  updateList(id: string, listData: UpdateListData): Observable<number> {
    return from(this.transaction('rw', this.lists, async () => {
      const list: ListDBUpdateType = {
        name: listData.name,
        comment: listData.comment || undefined,
        imageId: listData.imageId || undefined,
      };

      return this.lists.update(id, list);
    }));
  }

  deleteList(id: string): Observable<void> {
    return from(this.lists.delete(id));
  }

  async createImage(image: Blob): Promise<string> {
    const imageDB: ImageDBInsertType = {
      data: image,
      updatedAt: new Date().getTime()
    };

    return this.images.add(imageDB);
  }

  createImage$(image: Blob): Observable<string> {
    return from(this.createImage(image));
  }

  async getImageById(imageId: string): Promise<Blob> {
    const imageDB = await this.images.get(imageId);
    if (!imageDB) {
      throw new Error(`Image with id ${imageId} not found`);
    }
    return imageDB?.data;
  }
}
